import{z as l,x as B,o as t,c as D,q as s,j as i,D as r,d as E,s as o,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"SRT 除法","description":"","frontmatter":{"title":"SRT 除法","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/srt-division.md","filePath":"cs/srt-division.md","lastUpdated":1791063341000}'),d={name:"cs/srt-division.md"};function p(m,a,c,h,T,R){const A=B("Mermaid");return t(),D("div",null,[a[2]||(a[2]=s('<h1 id="srt-除法" tabindex="-1">SRT 除法 <a class="header-anchor" href="#srt-除法" aria-label="Permalink to &quot;SRT 除法&quot;">​</a></h1><div class="epigraph"><p>商数字若允许冗余，就不必等余数的完整符号才决定这一位：用最高几位查表，每步可以切出两位甚至更多。</p><footer>—— 据 Robertson, A New Class of Digital Division Methods, IRE Trans. 1958；Ercegovac and Lang, Digital Arithmetic 整理</footer></div><p><a href="/cs/restoring-division">上一课</a>的恢复/不恢复每步只定 1 比特商，且试减往往要看完整余数符号。缺口是延迟：64 位除要几十拍，卡住整数单元。SRT（Sweeney–Robertson–Tocher）用<strong>冗余商数字</strong>和余数的高位近似，让每步切 \\(r\\) 位。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>不恢复除法已经允许中间余数为负，商比特仍是 \\(0/1\\)。若商数字取自 \\(\\{\\bar 1,0,1\\}\\) 或更宽（基-4 SRT 用 \\(\\{\\bar 2,\\ldots,2\\}\\)），同一数值可有多种表示，选择不必精确。缺口因此不是再写一遍移位减，而是：<strong>用余数与除数的最高若干比特查表</strong>，选出商数字 \\(q_i\\)，做 \\(R\\leftarrow rR - q_i D\\)，余数保持在可纠正的窗口内。</p><p>Pentium FDIV 的著名缺陷正是 SRT 表漏项——本课用它当边界警告，不写勘误表。</p><h3 id="冗余不是「商可以随便错」" tabindex="-1">冗余不是「商可以随便错」 <a class="header-anchor" href="#冗余不是「商可以随便错」" aria-label="Permalink to &quot;冗余不是「商可以随便错」&quot;">​</a></h3><p>冗余保证：近似选择之后，下一步还能把误差吸收。最后必须把冗余表示收成常规补码商（片上加一次校正）。把 SRT 理解成近似除法，整数 <code>div</code> 的精确性合同会破。IEEE 754 要求正确舍入的除法，硬件仍要精确商，只是中间数字冗余。</p><p><span class="marginnote">Robertson 1958；Tocher 同期独立。Intel 的基-4 SRT 实现见各种微结构文献；教材级叙述见 Ercegovac/Lang 与 Parhami, <em>Computer Arithmetic</em>。Harris 通常不把 SRT 表画完，本课只钉机制。</span></p><p><span class="marginnote">直觉类比：冗余商数字像报站——不等到绝对精确才报「下一站」，而是先报个大概（-1、0、1 都可能指向同一个数），走错半步下一步能拽回来；终点前再做一次校正，把「大概的站名」收成精确地址。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>选定基 \\(r=2^k\\)。除数规格化到 \\([1/2,1)\\) 一类区间（整数除可先数前导零）。查表输入：余数高 \\(p\\) 位与除数高 \\(q\\) 位。输出 \\(q_i\\)。部分余数用 CSA 更新，避免每步 CLA——与<a href="/cs/wallace-carry-save">华莱士</a>同一压缩思想，用在迭代里。最后一次传播进位，若余数为负则商减 1 并加回除数。</p>',12)),(t(),i(n,null,{default:r(()=>[o(A,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20RD%5B%22%E4%BD%99%E6%95%B0%E9%AB%98%E4%BD%8D%20%2B%20%E9%99%A4%E6%95%B0%E9%AB%98%E4%BD%8D%22%5D%20--%3E%20LUT%5B%22%E5%95%86%E6%95%B0%E5%AD%97%E8%A1%A8%22%5D%0A%20%20LUT%20--%3E%20UPD%5B%22rR%20-%20qD%EF%BC%88CSA%EF%BC%89%22%5D%0A%20%20UPD%20--%3E%20RD%0A%20%20UPD%20--%3E%20CORR%5B%22%E7%BB%93%E6%9D%9F%E6%A0%A1%E6%AD%A3%E4%B8%BA%E7%B2%BE%E7%A1%AE%E5%95%86%22%5D%0A%20%20CORR%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E7%89%9B%E9%A1%BF%E5%80%92%E6%95%B0%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"基越高，每步位数越多，表越大、余数窗口越紧。Pentium 的表是基-4 的实现选择，不是 SRT 定义本身。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[E("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,[E("后课牛顿迭代走乘法器求倒数，适合已有快速 "),e("a",{href:"/cs/fp-mul-fma"},"FMA"),E(" 的浮点通路；SRT 适合整数与浮点共用的移位–加单元。微处理器常：整数除 SRT 或恢复，浮点除 SRT 或 Goldschmidt。本课不把两种都画进同一框图。")],-1)),(t(),i(n,null,{default:r(()=>[o(A,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%2264%20%E4%BD%8D%E9%99%A4%E6%B3%95%E9%80%89%E5%9F%BA%20r%20%3D%202%5Ek%22%5D%20--%3E%20K1%5B%22%E5%9F%BA%202%3A%20%E5%95%86%E6%95%B0%E5%AD%97%20%7B-1%2C0%2C1%7D%3Cbr%2F%3E%E6%AF%8F%E6%AD%A5%201%20%E4%BD%8D%2C%2064%20%E6%AD%A5%2C%20%E8%A1%A8%E5%BE%88%E5%B0%8F%22%5D%0A%20%20R%20--%3E%20K2%5B%22%E5%9F%BA%204%3A%20%E5%95%86%E6%95%B0%E5%AD%97%20%7B-2..2%7D%3Cbr%2F%3E%E6%AF%8F%E6%AD%A5%202%20%E4%BD%8D%2C%2032%20%E6%AD%A5%2C%20%E8%A1%A8%E7%BA%A6%205%20%E5%88%97%22%5D%0A%20%20R%20--%3E%20K3%5B%22%E5%9F%BA%208%20%E6%88%96%E6%9B%B4%E9%AB%98%3A%20%E6%95%B0%E5%AD%97%E6%9B%B4%E5%A4%9A%3Cbr%2F%3E%E6%AF%8F%E6%AD%A5%203%2B%20%E4%BD%8D%2C%20%E8%A1%A8%E9%99%A1%E5%A2%9E%2C%20%E4%BD%99%E6%95%B0%E7%AA%97%E5%8F%A3%E6%9B%B4%E7%B4%A7%22%5D%0A%20%20K2%20--%3E%20MID%5B%22%E4%B8%BB%E6%B5%81%E9%80%89%E6%8B%A9%3A%20%E8%BF%AD%E4%BB%A3%E6%AC%A1%E6%95%B0%E4%B8%8E%3Cbr%2F%3E%E6%9F%A5%E6%89%BE%E8%A1%A8%E9%9D%A2%E7%A7%AF%E6%8A%98%E4%B8%AD%22%5D%0A%20%20K1%20--%3E%20SLOW%5B%22%E6%AD%A5%E6%95%B0%E5%A4%9A%E4%BD%86%E6%8E%A7%E5%88%B6%E7%AE%80%E5%8D%95%22%5D%0A%20%20K3%20--%3E%20RISK%5B%22%E8%A1%A8%E6%BC%8F%E9%A1%B9%E5%8D%B3%E5%87%BA%E9%94%99%3Cbr%2F%3EFDIV%20%E6%95%99%E8%AE%AD%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=s('<p><span class="marginnote">数字实例：64 位被除数，基 2 每步切 1 位商要 64 步；基 4 每步 2 位只要 32 步；基 8 每步 3 位约 22 步——但基 8 的商数字集有 9 个候选，查表输入位宽也要加宽，表面积不是线性涨，实现代价很快超过省下的拍数。</span></p><p><span class="marginnote">常见误区：以为查表要等完整余数算出来。SRT 恰恰相反——只用部分余数和除数的最高几位做索引，低位还在 CSA 压缩树里没传播进位；等全宽结果就退化回恢复除法的延迟了。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不给完整商选择表，不分析 Pentium FDIV 的具体漏项坐标。不引入 Goldschmidt 级数。也不把验证用的形式化除法证明写进来——那是<a href="/cs/proof-assistants">证明助手</a>另一课程已结束的技能，本课只做电路。</p><p>后课默认：SRT 用冗余商数字与短余数估计加速迭代除；最终校正后仍是精确商。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>恢复/不恢复每步 1 比特；SRT 用冗余让每步切 \\(k\\) 位。</li><li>查表只看高位；CSA 更新部分余数；结束校正。</li><li>表不完整会错（FDIV）；语义仍是精确除。</li><li>出处：Robertson, <em>IRE Trans.</em>, 1958；Ercegovac and Lang；Parhami, <em>Computer Arithmetic</em>。</li></ul>',7))])}const f=l(d,[["render",p]]);export{S as __pageData,f as default};
